class Solution {
    string lower(string s) {
        for (char& c : s) c = tolower((unsigned char)c);
        return s;
    }
    string devowel(string s) {
        for (char& c : s) if (c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u') c = '*';
        return s;
    }
public:
    vector<string> spellchecker(vector<string>& wordlist, vector<string>& queries) {
        unordered_set<string> exact(wordlist.begin(), wordlist.end());
        unordered_map<string,string> caseMap, vowelMap;
        for (const string& w : wordlist) {
            string key = lower(w);
            if (!caseMap.count(key)) caseMap[key] = w;
            string pattern = devowel(key);
            if (!vowelMap.count(pattern)) vowelMap[pattern] = w;
        }
        vector<string> answer;
        for (const string& q : queries) {
            string key = lower(q), pattern = devowel(key);
            if (exact.count(q)) answer.push_back(q);
            else if (caseMap.count(key)) answer.push_back(caseMap[key]);
            else if (vowelMap.count(pattern)) answer.push_back(vowelMap[pattern]);
            else answer.push_back("");
        }
        return answer;
    }
};
